#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    int global_max = 0;

    #pragma omp parallel for reduction(max:global_max)
    for (size_t i = 0; i < N; ++i) {
        int degree = 0;
        const size_t row_start = i * N;

        for (size_t j = 0; j < N; ++j) {
            degree += A[row_start + j];
        }

        if (degree > global_max) {
            global_max = degree;
        }
    }

    return global_max;
}
